//! Gmail seed corpus (`tests/fixtures/imap/seed/gmail/`): loading, substitution
//! for a real run, and what each message must produce once exported.
//!
//! The corpus is generated by `tests/fixtures/imap/gmail/build_seed.py`. Every
//! expectation is the *wanted* result: a message whose export still differs is
//! tested with `#[ignore = "#NN …"]` at the call site, never by weakening it here.

use email_to_markdown::contextual_export::{read_server_hold, read_source_proof};
use email_to_markdown::email_block;
use std::path::{Path, PathBuf};

/// Run label of the versioned `.eml` (`[email-to-markdown seed fixture]`).
pub const FIXTURE_RUN: &str = "fixture";
pub const FIXTURE_ALICE: &str = "Alice Martin <alice@example.com>";
pub const FIXTURE_BOB: &str = "Bob Durand <bob@example.com>";

pub fn seed_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/imap/seed/gmail")
}

pub fn generator() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/imap/gmail/build_seed.py")
}

pub fn load(file: &str) -> Vec<u8> {
    let path = seed_dir().join(file);
    std::fs::read(&path).unwrap_or_else(|e| panic!("read {}: {e}", path.display()))
}

/// Rewrite a seed message for a real run: `From`, `To`, and the run label of the
/// subject and of `Message-ID` / `In-Reply-To` / `References`. Only the top-level
/// header block changes; every byte of the body is kept.
pub fn substitute(raw: &[u8], run: &str, from: &str, to: &str) -> Vec<u8> {
    let split = raw
        .windows(4)
        .position(|w| w == b"\r\n\r\n")
        .expect("seed message has a header block");
    let (head, body) = raw.split_at(split);
    let head = std::str::from_utf8(head).expect("seed headers are ASCII");
    let old_tag = format!("seed {FIXTURE_RUN}]");
    let new_tag = format!("seed {run}]");
    let old_id = format!(".{FIXTURE_RUN}@email-to-markdown.test>");
    let new_id = format!(".{run}@email-to-markdown.test>");
    let rewritten: Vec<String> = head
        .split("\r\n")
        .map(|line| {
            if line.starts_with("From: ") {
                format!("From: {from}")
            } else if line.starts_with("To: ") {
                format!("To: {to}")
            } else if line.starts_with("Subject: ") {
                line.replacen(&old_tag, &new_tag, 1)
            } else if ["Message-ID: ", "In-Reply-To: ", "References: "]
                .iter()
                .any(|h| line.starts_with(h))
            {
                line.replace(&old_id, &new_id)
            } else {
                line.to_string()
            }
        })
        .collect();
    let mut out = rewritten.join("\r\n").into_bytes();
    out.extend_from_slice(body);
    out
}

/// What one seed message must produce. Images are checked by content, not by
/// name: in a shared export directory a name gets a suffix, never overwritten.
#[derive(Debug)]
pub struct SeedExpectation {
    /// `seed-cN-mN`, prefix of the `Message-ID`, read back from the note's `source`.
    pub key: &'static str,
    pub file: &'static str,
    /// Decoded subject of the ```email block.
    pub subject: &'static str,
    /// Local `![[…]]` entries of `### Images :`, in MIME order of their parts.
    pub images: usize,
    /// Substrings of the `- [[…]]` entries of `### Pieces jointes :`, in order.
    pub attachments: &'static [&'static str],
    /// URLs found whole in `### Liens :` or in the body.
    pub links: &'static [&'static str],
    /// MIME names of the parts the signature filter quarantines in `_skipped/`.
    pub skipped: &'static [&'static str],
    pub body_contains: &'static [&'static str],
    pub body_excludes: &'static [&'static str],
    /// A `[image: …]` marker without image part stays as is (C3-M9).
    pub keep_image_marker: bool,
    /// The note's `keep_on_server` holds this message on the server.
    pub held_by_guard: bool,
}

