pub fn expectation(key: &str) -> &'static SeedExpectation {
    CATALOGUE
        .iter()
        .find(|e| e.key == key)
        .unwrap_or_else(|| panic!("no seed expectation for {key}"))
}

/// Decoded content of every `image/*` leaf of a message, in MIME order.
pub fn image_parts(raw: &[u8]) -> Vec<(String, Vec<u8>)> {
    fn walk(part: &mailparse::ParsedMail, out: &mut Vec<(String, Vec<u8>)>) {
        if part.subparts.is_empty() {
            if part
                .ctype
                .mimetype
                .to_ascii_lowercase()
                .starts_with("image/")
            {
                let name = part.ctype.params.get("name").cloned().unwrap_or_default();
                out.push((name, part.get_body_raw().expect("decode image part")));
            }
        } else {
            part.subparts.iter().for_each(|p| walk(p, out));
        }
    }
    let mail = mailparse::parse_mail(raw).expect("parse seed message");
    let mut out = Vec::new();
    walk(&mail, &mut out);
    out
}

/// Lines of a `### <title> :` section of the note, up to the next section.
fn section<'a>(note: &'a str, title: &str) -> Vec<&'a str> {
    let heading = format!("### {title} :");
    let mut lines = note.lines().skip_while(|l| l.trim() != heading);
    if lines.next().is_none() {
        return Vec::new();
    }
    lines
        .take_while(|l| !l.starts_with("### "))
        .map(str::trim)
        .filter(|l| !l.is_empty())
        .collect()
}

/// `attachments:` list of the frontmatter.
fn frontmatter_attachments(note: &str) -> Vec<String> {
    let front = note
        .strip_prefix("---\n")
        .and_then(|rest| rest.split("\n---").next())
        .unwrap_or_default();
    front
        .lines()
        .skip_while(|l| *l != "attachments:")
        .skip(1)
        .take_while(|l| l.starts_with("- "))
        .map(|l| {
            l[2..]
                .trim()
                .trim_matches('\'')
                .trim_matches('"')
                .to_string()
        })
        .collect()
}

fn files_under(dir: &Path) -> Vec<PathBuf> {
    let mut out = Vec::new();
    if let Ok(entries) = std::fs::read_dir(dir) {
        for entry in entries.flatten() {
            let path = entry.path();
            if path.is_dir() {
                out.extend(files_under(&path));
            } else {
                out.push(path);
            }
        }
    }
    out
}

/// Check one exported note against its expectation. `raw` is the message the
/// note comes from, `quarantined` the count reported by the conversion, and
/// `skipped_dir` the account's `<export>/_skipped`.
pub fn assert_seed_note(
    note_path: &Path,
    raw: &[u8],
    quarantined: usize,
    skipped_dir: &Path,
    exp: &SeedExpectation,
) {
    let key = exp.key;
    let note = std::fs::read_to_string(note_path)
        .unwrap_or_else(|e| panic!("{key}: read {}: {e}", note_path.display()));
    let dir = note_path.parent().expect("note has a directory");

    // Source proof: the note is found by its Message-ID, and feeds the ledger.
    let proof = read_source_proof(note_path)
        .unwrap_or_else(|e| panic!("{key}: unreadable source proof: {e}"))
        .unwrap_or_else(|| panic!("{key}: note has no source proof"));
    let message_id = proof.identity.message_id.unwrap_or_default();
    assert!(
        message_id.starts_with(&format!("{key}.")),
        "{key}: source.identity.message_id is {message_id:?}"
    );
    // Deletion guard: only the expected messages hold their server copy.
    let hold = read_server_hold(note_path)
        .unwrap_or_else(|e| panic!("{key}: unreadable frontmatter: {e}"));
    assert_eq!(
        hold.is_some(),
        exp.held_by_guard,
        "{key}: keep_on_server is {hold:?}"
    );

    let header = email_block::read_header(&note)
        .unwrap_or_else(|| panic!("{key}: ```email block does not parse as TOML"));
    assert_eq!(header.subject, exp.subject, "{key}: decoded subject");
    let body = email_block::read_body(&note)
        .unwrap_or_else(|| panic!("{key}: ```email block has no body or does not parse as TOML"));
    assert!(
        !note.contains("=?UTF-8?"),
        "{key}: encoded-word left in the note"
    );

    for fragment in exp.body_contains {
        assert!(
            body.contains(fragment),
            "{key}: body lacks {fragment:?}\n---\n{body}"
        );
    }
    for fragment in exp.body_excludes {
        assert!(
            !body.contains(fragment),
            "{key}: body contains {fragment:?}\n---\n{body}"
        );
    }
    if !exp.keep_image_marker {
        assert!(
            !body.contains("[image:"),
            "{key}: [image: …] marker left\n---\n{body}"
        );
    }
    for line in body.lines() {
        let line = line.trim_start_matches(['>', ' ']);
        assert!(
            !line.starts_with('«') && !line.starts_with('»'),
            "{key}: line cut before a guillemet: {line:?}"
        );
    }

    let links = section(&note, "Liens");
    for url in exp.links {
        let in_links = links.iter().any(|l| l.ends_with(&format!("]({url})")));
        assert!(
            in_links || body.contains(url),
            "{key}: URL {url} neither in ### Liens : nor in the body\n---\n{note}"
        );
    }

    // Every attachment of the frontmatter is on disk, with a decoded name.
    let listed = frontmatter_attachments(&note);
    for name in &listed {
        assert!(
            dir.join(name).is_file(),
            "{key}: attachment {name} missing on disk"
        );
        assert!(
            !name.contains("UTF-8''") && !name.contains("%20"),
            "{key}: attachment name not decoded: {name}"
        );
    }

    // ### Images : local entries, each a written file of this message, in MIME order.
    let parts = image_parts(raw);
    let local_images: Vec<String> = section(&note, "Images")
        .into_iter()
        .filter_map(|l| l.strip_prefix("![[").and_then(|l| l.strip_suffix("]]")))
        .map(str::to_string)
        .collect();
    assert_eq!(
        local_images.len(),
        exp.images,
        "{key}: ### Images : entries {local_images:?}\n---\n{note}"
    );
    let mut last = None;
    for name in &local_images {
        assert!(
            listed.contains(name),
            "{key}: image {name} not in frontmatter attachments"
        );
        let bytes =
            std::fs::read(dir.join(name)).unwrap_or_else(|e| panic!("{key}: read {name}: {e}"));
        let index = parts
            .iter()
            .position(|(_, data)| *data == bytes)
            .unwrap_or_else(|| panic!("{key}: {name} matches no image part (overwritten?)"));
        assert!(
            last.is_none_or(|l| index > l),
            "{key}: ### Images : out of MIME order"
        );
        last = Some(index);
    }

    let pieces = section(&note, "Pieces jointes");
    assert_eq!(
        pieces.len(),
        exp.attachments.len(),
        "{key}: ### Pieces jointes : {pieces:?}"
    );
    for (line, wanted) in pieces.iter().zip(exp.attachments) {
        assert!(
            line.starts_with("- [[") && line.contains(wanted),
            "{key}: attachment entry {line:?} should name {wanted:?}"
        );
    }

    // Invariant of #19: each image part is written for this note, or quarantined.
    let written: Vec<Vec<u8>> = listed
        .iter()
        .filter_map(|name| std::fs::read(dir.join(name)).ok())
        .collect();
    let skipped_files: Vec<Vec<u8>> = files_under(skipped_dir)
        .iter()
        .filter_map(|p| std::fs::read(p).ok())
        .collect();
    let mut missing = Vec::new();
    for (name, data) in &parts {
        if written.contains(data) {
            continue;
        }
        assert!(
            skipped_files.contains(data),
            "{key}: image part {name:?} neither written nor quarantined"
        );
        missing.push(name.as_str());
    }
    let mut want_skipped: Vec<&str> = exp.skipped.to_vec();
    want_skipped.sort_unstable();
    missing.sort_unstable();
    assert_eq!(missing, want_skipped, "{key}: quarantined parts");
    assert_eq!(quarantined, exp.skipped.len(), "{key}: quarantined count");
}
